def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Make a copy of the grid
    output = [row[:] for row in grid]

    # First pass: identify background and special values
    values = set()
    for r in range(rows):
        for c in range(cols):
            values.add(grid[r][c])

    # Most common value is background, other is special
    if len(values) >= 2:
        val_counts = {}
        for r in range(rows):
            for c in range(cols):
                val = grid[r][c]
                val_counts[val] = val_counts.get(val, 0) + 1
        sorted_vals = sorted(val_counts.items(), key=lambda x: x[1], reverse=True)
        background = sorted_vals[0][0]
    else:
        return grid  # nothing to process

    # Check for all possible special values in case of multiple
    special_values = [v for v in values]

    for r in range(rows):
        for c in range(1, cols - 1):
            left = grid[r][c - 1]
            right = grid[r][c + 1]
            center = grid[r][c]

            # If left and right are the same value (special value)
            # and center is background, change center to 2
            if left == right and left != center:
                output[r][c] = 2

    return output
